CREATE TABLE units (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome VARCHAR(120) NOT NULL, endereco VARCHAR(250) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE users (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome VARCHAR(120) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE,
 password_hash VARCHAR(255) NOT NULL, perfil VARCHAR(20) NOT NULL CHECK(perfil IN ('CLIENTE','ATENDENTE','COZINHA','GERENTE','ADMIN')),
 unidade_id BIGINT REFERENCES units(id), active BOOLEAN NOT NULL DEFAULT TRUE,
 consent BOOLEAN NOT NULL DEFAULT FALSE, consent_at VARCHAR(50), consent_version VARCHAR(10),
 points BIGINT NOT NULL DEFAULT 0 CHECK(points>=0), created_at VARCHAR(50) NOT NULL
);
CREATE TABLE products (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome VARCHAR(120) NOT NULL, descricao VARCHAR(500) NOT NULL DEFAULT '', active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE stocks (unidade_id BIGINT NOT NULL REFERENCES units(id), produto_id BIGINT NOT NULL REFERENCES products(id), quantidade BIGINT NOT NULL CHECK(quantidade>=0), preco_centavos BIGINT NOT NULL CHECK(preco_centavos>0), PRIMARY KEY(unidade_id,produto_id));
CREATE TABLE orders (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, cliente_id BIGINT NOT NULL REFERENCES users(id), unidade_id BIGINT NOT NULL REFERENCES units(id),
 canal_pedido VARCHAR(20) NOT NULL CHECK(canal_pedido IN ('APP','TOTEM','BALCAO','PICKUP','WEB')),
 status VARCHAR(30) NOT NULL CHECK(status IN ('AGUARDANDO_PAGAMENTO','EM_PREPARO','PRONTO','ENTREGUE','CANCELADO')),
 subtotal_centavos BIGINT NOT NULL, desconto_centavos BIGINT NOT NULL, total_centavos BIGINT NOT NULL CHECK(total_centavos>=0),
 pontos_resgate BIGINT NOT NULL DEFAULT 0, pontos_concedidos BIGINT NOT NULL DEFAULT 0, created_at VARCHAR(50) NOT NULL, updated_at VARCHAR(50) NOT NULL
);
CREATE TABLE order_items (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, pedido_id BIGINT NOT NULL REFERENCES orders(id), produto_id BIGINT NOT NULL REFERENCES products(id), nome_produto VARCHAR(120) NOT NULL, quantidade BIGINT NOT NULL CHECK(quantidade>0), preco_centavos BIGINT NOT NULL CHECK(preco_centavos>0), UNIQUE(pedido_id,produto_id));
CREATE TABLE payments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, pedido_id BIGINT NOT NULL REFERENCES orders(id), status VARCHAR(20) NOT NULL CHECK(status IN ('APROVADO','NEGADO','ERRO','ESTORNADO')), valor_centavos BIGINT NOT NULL, provider_payload TEXT NOT NULL, created_at VARCHAR(50) NOT NULL);
CREATE TABLE stock_movements (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, unidade_id BIGINT NOT NULL, produto_id BIGINT NOT NULL, quantidade BIGINT NOT NULL, motivo VARCHAR(120) NOT NULL, pedido_id BIGINT REFERENCES orders(id), actor_id BIGINT NOT NULL REFERENCES users(id), created_at VARCHAR(50) NOT NULL, FOREIGN KEY(unidade_id,produto_id) REFERENCES stocks(unidade_id,produto_id));
CREATE TABLE loyalty_movements (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), pedido_id BIGINT REFERENCES orders(id), quantidade BIGINT NOT NULL, motivo VARCHAR(120) NOT NULL, created_at VARCHAR(50) NOT NULL);
CREATE TABLE audit (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, actor_id BIGINT NOT NULL REFERENCES users(id), acao VARCHAR(80) NOT NULL, recurso VARCHAR(100) NOT NULL, created_at VARCHAR(50) NOT NULL);
CREATE TABLE idempotency (actor_id BIGINT NOT NULL REFERENCES users(id), operacao VARCHAR(30) NOT NULL, chave VARCHAR(100) NOT NULL, fingerprint VARCHAR(64) NOT NULL, recurso_id BIGINT NOT NULL, PRIMARY KEY(actor_id,operacao,chave));
CREATE INDEX idx_orders_unit_channel ON orders(unidade_id,canal_pedido,status);
CREATE INDEX idx_orders_client ON orders(cliente_id,id);
CREATE INDEX idx_payments_order ON payments(pedido_id);
CREATE INDEX idx_audit_actor ON audit(actor_id,id);
